// Package testsupport provides small, real media fixtures shared by evidence-gate tests.
package testsupport

import "encoding/base64"

const reviewableAVIBase64 = ""

const reviewableWebMBase64 = ""

const reviewablePNGBase64 = ""

// ReviewableWebM returns a minimal valid WebM container, not renamed text.
func ReviewableWebM() []byte {
	return decodeMedia(reviewableWebMBase64)
}

// ReviewableWebMBase64 returns the fixture for shell-driven integration tests.
func ReviewableWebMBase64() string {
	return reviewableWebMBase64
}

// ReviewableAVI returns a minimal playable AVI container in a format distinct from WebM.
func ReviewableAVI() []byte {
	return decodeMedia(reviewableAVIBase64)
}

// ReviewablePNG returns a decodable 160×90 PNG image.
func ReviewablePNG() []byte {
	return decodeMedia(reviewablePNGBase64)
}

// decodeMedia converts an embedded fixture and panics only if the source constant is corrupt.
func decodeMedia(encoded string) []byte {
	data, err := base64.StdEncoding.DecodeString(encoded)
	if err != nil {
		panic(err)
	}
	return data
}
